    private List<SettingHit> findSettings(String query) {
        if (query.isBlank()) {
            return VLRestrictions.cleanRows(List.of());
        }
        if (!this.indexedLanguage.equals(this.cfg().language)) {
            this.settingIndex.clear();
            this.indexingSettings = true;
            try {
                for (Module module : (Module[])VLRestrictions.visibleModules((Object[])Module.values())) {
                    if (BloodHelperScreen.nestedModule(module) || BloodHelperScreen.isStaff(module)) continue;
                    this.indexingModule = module;
                    this.rows(module);
                }
                this.indexingModule = null;
                this.appearance(null);
            }
            finally {
                this.indexingSettings = false;
                this.indexingModule = null;
            }
            this.indexedLanguage = this.cfg().language;
            this.lastSettingQuery = "";
        }
        if (!query.equals(this.lastSettingQuery) || this.indexedPage != this.page) {
            this.indexedPage = this.page;
            this.matchedSettings = this.settingIndex.stream().filter(hit -> !BloodHelperScreen.isStaff(hit.module)).filter(hit -> ItemSearchQuery.matches((String)(hit.name + " " + hit.description), (String)query)).limit(60L).toList();
            this.lastSettingQuery = query;
        }
        return VLRestrictions.cleanRows(this.matchedSettings);
    }

