    private void section(List<Row> rows, String id, boolean open, Consumer<List<Row>> build) {
        List contents;
        if (this.indexingSettings) {
            build.accept(rows);
            return;
        }
        if (open) {
            contents = new ArrayList();
            build.accept(contents);
            this.retainedSections.put(id, List.copyOf(contents));
        } else {
            contents = this.retainedSections.getOrDefault(id, List.of());
        }
        int wanted = contents.stream().mapToInt(Row::height).sum();
        int height = (int)Math.round(this.animateLayout(id + ".height", open ? (double)wanted : 0.0));
        if (!open && height <= 0) {
            this.retainedSections.remove(id);
            return;
        }
        List shown = contents;
        rows.add(new Row(height, (g, x, y, w) -> this.drawRowsClipped(g, shown, x, y, w, height, open)));
    }

