    private void featureSection(List<Row> rows, String id, String title, Module feature) {
        rows.add(this.disclosure(id, title));
        this.section(rows, id, contents -> {
            contents.add(this.featureToggle(feature, title));
            contents.addAll(this.moduleRows(feature));
        });
    }

