    private String musicStatus() {
        return switch (BloodHelperClient.mediaStatus()) {
            case "playing" -> this.tr("\u0412\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u0435\u0434\u0435\u043d\u0438\u0435", "Playing");
            case "paused" -> this.tr("\u041d\u0430 \u043f\u0430\u0443\u0437\u0435", "Paused");
            case "unsupported_os" -> this.tr("\u041f\u043b\u0435\u0435\u0440\u044b \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0432 Windows \u0438 Linux", "Players are supported on Windows and Linux");
            case "unavailable" -> {
                String detail = BloodHelperClient.media().diagnostic();
                if (detail.contains("missing_python3")) {
                    yield this.tr("\u0414\u043b\u044f \u043f\u043b\u0435\u0435\u0440\u043e\u0432 Linux \u043d\u0443\u0436\u0435\u043d Python 3", "Linux players require Python 3");
                }
                if (detail.contains("missing_busctl")) {
                    yield this.tr("\u0414\u043b\u044f \u043f\u043b\u0435\u0435\u0440\u043e\u0432 Linux \u043d\u0443\u0436\u0435\u043d busctl", "Linux players require busctl");
                }
                if (detail.contains("session_bus_unavailable")) {
                    yield this.tr("\u041d\u0435\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u0441\u0435\u0430\u043d\u0441\u0443 \u0440\u0430\u0431\u043e\u0447\u0435\u0433\u043e \u0441\u0442\u043e\u043b\u0430", "Desktop session is unavailable");
                }
                yield this.tr("\u041f\u043b\u0435\u0435\u0440 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d", "Player unavailable");
            }
            case "no_session" -> this.tr("\u0412\u043a\u043b\u044e\u0447\u0438 \u043c\u0443\u0437\u044b\u043a\u0443 \u0432 \u043f\u043b\u0435\u0435\u0440\u0435", "Start music in your player");
            case "starting" -> this.tr("\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u043a \u043f\u043b\u0435\u0435\u0440\u0443\u2026", "Connecting to player\u2026");
            default -> this.tr("\u041c\u0443\u0437\u044b\u043a\u0430 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u0430", "No music found");
        };
    }

    private void openThemePicker() {
        this.closeDropdown();
        this.closingDropdown = null;
        this.focus(null);
        this.capturingKey = false;
        this.pressedControl = "";
        this.colorPicker = new ThemeColorPicker(this.cfg().accent, this.ru(), color -> {
            this.cfg().accent = color;
            ChatTools.refreshTimestampColors();
        }, () -> {
            this.colorPicker = null;
            this.save();
        });
    }

